//! Core image resizing engine built on the vendored ImageMagick MagickWand C API.
//!
//! The bindings in `magickwand_bindings.rs` are generated by `bindgen` in
//! `build.rs` at compile time. All wand pointers are manual resources, so
//! helper closures/functions are kept small and destroy wands on all paths.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::wildcard_imports, dead_code)]

use std::ffi::{CStr, CString, c_void};
use std::path::{Path, PathBuf};
use std::sync::Once;

use thiserror::Error;

include!(concat!(env!("OUT_DIR"), "/magickwand_bindings.rs"));

/// Specification of a single resized output for one input file.
#[derive(Debug, Clone)]
pub struct OutputSpec {
    /// Target width in pixels. Height is derived from the aspect ratio.
    pub width: u32,
    /// Full destination path, e.g. `<dir>/<stem>_w200.png`.
    pub path: PathBuf,
    /// Output format/extension override (e.g. "webp"). None keeps the input format.
    pub format: Option<String>,
    /// Compression quality for lossy formats (0-100).
    pub quality: Option<u8>,
}

#[derive(Debug, Error)]
pub enum ImagingError {
    #[error("cannot open {path}: {message}")]
    Read { path: PathBuf, message: String },
    #[error("cannot resize to width {width}: {message}")]
    Resize { width: u32, message: String },
    #[error("cannot write {path}: {message}")]
    Write { path: PathBuf, message: String },
}

static GENESIS: Once = Once::new();

/// Must be called once per process before any MagickWand use. Thread-safe.
pub fn ensure_genesis() {
    GENESIS.call_once(|| unsafe {
        MagickWandGenesis();
    });
}

/// Destroys ImageMagick resources at process exit. `MagickWandTerminus`
/// must run exactly once after genesis; the CLI relies on process teardown,
/// so this is a no-op placeholder kept for API symmetry.
pub fn shutdown() {}

/// Retrieve and release the last exception message from a wand.
unsafe fn take_exception(wand: *mut MagickWand) -> String {
    let mut severity: ExceptionType = 0;
    let ptr = unsafe { MagickGetException(wand, &mut severity) };
    if ptr.is_null() {
        return "unknown exception".to_string();
    }
    let message = unsafe { CStr::from_ptr(ptr).to_string_lossy().into_owned() };
    unsafe { MagickRelinquishMemory(ptr as *mut c_void) };
    message
}

/// Resize `input` and write the result to `spec.path`.
///
/// Mirrors `magick -resize <N>x`: fit to the requested width, preserve the
/// aspect ratio, never upscale (images narrower than the requested width are
/// written unchanged).
pub fn resize_file(input: &Path, spec: &OutputSpec) -> Result<(), ImagingError> {
    ensure_genesis();

    let input_c = path_to_cstring(input, |e| ImagingError::Read {
        path: input.to_path_buf(),
        message: e,
    })?;

    unsafe {
        let wand = NewMagickWand();
        if wand.is_null() {
            return Err(ImagingError::Read {
                path: input.to_path_buf(),
                message: "failed to allocate MagickWand".into(),
            });
        }

        let result = run_resize(wand, input, &input_c, spec);
        DestroyMagickWand(wand);
        result
    }
}

unsafe fn run_resize(
    wand: *mut MagickWand,
    input: &Path,
    input_c: &CString,
    spec: &OutputSpec,
) -> Result<(), ImagingError> {
    // Edition 2024 requires explicit unsafe blocks even inside unsafe fns.
    unsafe {
        if MagickReadImage(wand, input_c.as_ptr()) == MagickBooleanType_MagickFalse {
            return Err(ImagingError::Read {
                path: input.to_path_buf(),
                message: take_exception(wand),
            });
        }

        let src_width = MagickGetImageWidth(wand);
        let src_height = MagickGetImageHeight(wand);
        if src_width == 0 || src_height == 0 {
            return Err(ImagingError::Read {
                path: input.to_path_buf(),
                message: "image has zero dimensions".into(),
            });
        }

        // No-upscale: `magick -resize 200x` leaves narrower images untouched.
        let (new_width, new_height) = if spec.width as usize >= src_width {
            (src_width, src_height)
        } else {
            let ratio = src_height as f64 / src_width as f64;
            (
                spec.width as usize,
                (spec.width as f64 * ratio).round() as usize,
            )
        };

        if MagickResizeImage(wand, new_width, new_height, FilterType_LanczosFilter)
            == MagickBooleanType_MagickFalse
        {
            return Err(ImagingError::Resize {
                width: spec.width,
                message: take_exception(wand),
            });
        }

        if let Some(format) = &spec.format {
            let fmt = CString::new(format.as_str()).expect("format contained NUL");
            if MagickSetImageFormat(wand, fmt.as_ptr()) == MagickBooleanType_MagickFalse {
                return Err(ImagingError::Write {
                    path: spec.path.clone(),
                    message: format!("cannot set format {format}: {}", take_exception(wand)),
                });
            }
        }

        if let Some(quality) = spec.quality
            && MagickSetImageCompressionQuality(wand, quality as usize)
                == MagickBooleanType_MagickFalse
        {
            return Err(ImagingError::Write {
                path: spec.path.clone(),
                message: format!("cannot set quality {quality}: {}", take_exception(wand)),
            });
        }

        let output_c = path_to_cstring(&spec.path, |e| ImagingError::Write {
            path: spec.path.clone(),
            message: e,
        })?;
        if MagickWriteImage(wand, output_c.as_ptr()) == MagickBooleanType_MagickFalse {
            return Err(ImagingError::Write {
                path: spec.path.clone(),
                message: take_exception(wand),
            });
        }
        Ok(())
    }
}

fn path_to_cstring<E>(path: &Path, map: impl FnOnce(String) -> E) -> Result<CString, E> {
    let bad = |message: String| map(message);
    match path.to_str() {
        None => Err(bad(format!("path is not valid UTF-8: {}", path.display()))),
        Some(s) => CString::new(s).map_err(|e| bad(format!("path contains NUL byte: {e}"))),
    }
}

/// Read the pixel dimensions of `path` (used by tests and CLI reporting).
pub fn image_dimensions(path: &Path) -> Result<(usize, usize), ImagingError> {
    ensure_genesis();
    let input_c = path_to_cstring(path, |e| ImagingError::Read {
        path: path.to_path_buf(),
        message: e,
    })?;
    unsafe {
        let wand = NewMagickWand();
        if wand.is_null() {
            return Err(ImagingError::Read {
                path: path.to_path_buf(),
                message: "failed to allocate MagickWand".into(),
            });
        }
        let result = if MagickReadImage(wand, input_c.as_ptr()) == MagickBooleanType_MagickFalse {
            Err(ImagingError::Read {
                path: path.to_path_buf(),
                message: take_exception(wand),
            })
        } else {
            Ok((MagickGetImageWidth(wand), MagickGetImageHeight(wand)))
        };
        DestroyMagickWand(wand);
        result
    }
}

/// Create a solid-color image at `width` x `height` and write it to `path`
/// in the format implied by the file extension. Used to generate test fixtures.
pub fn write_solid_image(path: &Path, width: usize, height: usize) -> Result<(), ImagingError> {
    ensure_genesis();
    let output_c = path_to_cstring(path, |e| ImagingError::Write {
        path: path.to_path_buf(),
        message: e,
    })?;
    unsafe {
        let wand = NewMagickWand();
        if wand.is_null() {
            return Err(ImagingError::Write {
                path: path.to_path_buf(),
                message: "failed to allocate MagickWand".into(),
            });
        }
        let pixel = NewPixelWand();
        PixelSetColor(pixel, c"white".as_ptr());
        let result =
            match MagickNewImage(wand, width, height, pixel) == MagickBooleanType_MagickFalse {
                true => Err(ImagingError::Write {
                    path: path.to_path_buf(),
                    message: take_exception(wand),
                }),
                false => {
                    if MagickWriteImage(wand, output_c.as_ptr()) == MagickBooleanType_MagickFalse {
                        Err(ImagingError::Write {
                            path: path.to_path_buf(),
                            message: take_exception(wand),
                        })
                    } else {
                        Ok(())
                    }
                }
            };
        DestroyPixelWand(pixel);
        DestroyMagickWand(wand);
        result
    }
}
